assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()), set(P.keys()) - set(IDS))
assert len(P) == 20, len(P)
os.makedirs(OUTDIR, exist_ok=True)
total = 0
for cid in IDS:
    rec = {"case_id": cid,
           "prediction_text": P[cid]["prediction_text"],
           "basis": P[cid]["basis"],
           "confidence": P[cid]["confidence"],
           "trigger": P[cid]["trigger"]}
    path = os.path.join(OUTDIR, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    # exact-path self-verify
    with open(path, encoding="utf-8") as f:
        back = json.load(f)
    assert back["case_id"] == cid
    assert set(back.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert set(back["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
    total += os.path.getsize(path)
cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
dp = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
print("written=%d total_bytes=%d changed_main=%d reserve_used=%d disputed=%d" % (len(IDS), total, cm, ru, dp))
